// A rough Sahara and Arabian desert band, drawn inside the land only.
// prettier-ignore
const DESERT: LonLat[] = [[-17,18],[-5,15],[5,14],[15,13.5],[25,14],[33,16],[38,17],[44,16],[52,17],[57,20],[58,24],[50,30],[44,32],[36,31],[30,31.5],[20,31],[10,33],[-2,32],[-10,29],[-17,22],[-17,18]];

// prettier-ignore
const CITIES: LonLat[] = [[-0.1,51.5],[2.35,48.86],[-3.7,40.4],[12.5,41.9],[13.4,52.5],[28.98,41.0],[31.2,30.0],[3.4,6.5],[-7.6,33.6],[37.6,55.75],[55.3,25.2],[46.7,24.7],[72.9,19.0],[77.2,28.6],[36.8,-1.3],[15.3,-4.3],[-0.2,5.6],[-17.4,14.7],[51.4,35.7],[67.0,24.9],[23.7,38.0],[18.07,59.33],[21.0,52.2],[30.5,50.45],[38.7,9.0],[32.6,0.3],[44.4,33.3],[4.9,52.4],[9.2,45.5],[-9.1,38.7]];

const CLOUDS: [LonLat, number, number, number][] = [
  [[-35, 8], 9, 1.6, 12],
  [[-22, 25], 7, 1.3, -18],
  [[-40, 34], 8, 1.4, 20],
  [[18, 0], 6, 1.2, 8],
  [[60, 5], 8, 1.4, -10],
  [[-5, 47], 6, 1.2, 15],
];

function inside([x, y]: LonLat, poly: LonLat[]) {
  let hit = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i];
    const [xj, yj] = poly[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) hit = !hit;
  }
  return hit;
}
const onLand = (p: LonLat) => Object.values(LAND).some((poly) => inside(p, poly));

// The globe as framed in the orbit scene: only its top shows above the bottom edge.
const GLOBE = { cx: 800, cy: 1270, R: 710, lon0: 8, lat0: -12 };

const RAD = Math.PI / 180;
function project([lon, lat]: LonLat): [number, number, number] {
  const { cx, cy, R, lon0, lat0 } = GLOBE;
  const f = lat * RAD;
  const l = (lon - lon0) * RAD;
  const f0 = lat0 * RAD;
  const facing = Math.sin(f0) * Math.sin(f) + Math.cos(f0) * Math.cos(f) * Math.cos(l);
  let x = R * Math.cos(f) * Math.sin(l);
  let y = R * (Math.cos(f0) * Math.sin(f) - Math.sin(f0) * Math.cos(f) * Math.cos(l));
  if (facing < 0) {
    // Behind the horizon: pin to the edge, so land wraps over it.
    const k = R / Math.hypot(x, y);
    x *= k;
    y *= k;
  }
  return [cx + x, cy - y, facing];
}

/** Adds points along long edges so outlines curve with the globe. */
function densify(poly: LonLat[]) {
  const out: LonLat[] = [];
  for (let i = 0; i < poly.length - 1; i++) {
    const [a, b] = [poly[i], poly[i + 1]];
    const n = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / 1.5));
    for (let k = 0; k < n; k++)
      out.push([a[0] + ((b[0] - a[0]) * k) / n, a[1] + ((b[1] - a[1]) * k) / n]);
  }
  return out;
}

const pathOf = (poly: LonLat[]) =>
  "M" +
  densify(poly)
    .map((p) => {
      const [x, y] = project(p);
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join("L") +
  "Z";

function ellipseAround([lon, lat]: LonLat, w: number, h: number, rot: number): LonLat[] {
  const k = rot * RAD;
  return Array.from({ length: 25 }, (_, i) => {
    const t = i * 15 * RAD;
    const ex = Math.cos(t) * w;
    const ey = Math.sin(t) * h;
    return [lon + ex * Math.cos(k) - ey * Math.sin(k), lat + ex * Math.sin(k) + ey * Math.cos(k)];
  });
}

type Light = { x: number; y: number; r: number; color: string; ring: boolean; big: boolean };

/** City lights: the big cities in their real places, then towns scattered over land. */
function makeLights(): Light[] {
  const visible = (p: LonLat) => {
    const [x, y, facing] = project(p);
    const clearOfLabel = !(x > 1270 && y > 755);
    return facing > 0.08 && y < 890 && x > 20 && x < 1580 && clearOfLabel
      ? { x: round(x), y: round(y), facing: round(facing) }
      : null;
  };
  const colors = [P.sun, P.sun, P.sun, P.pink, P.paper];
  const lights: Light[] = [];
  CITIES.forEach((p, i) => {
    const v = visible(p);
    if (v)
      lights.push({
        x: v.x,
        y: v.y,
        r: round(3 + 2.5 * v.facing),
        color: colors[i % colors.length],
        ring: i % 7 === 0 && v.facing > 0.4,
        big: true,
      });
  });
  const r = rng(9);
  for (let i = 0, n = 0; i < 20000 && n < 150; i++) {
    const p: LonLat = [-100 + r() * 200, -40 + r() * 112];
    if (!onLand(p)) continue;
    // Deserts stay mostly dark, except along the Nile.
    const nile = p[0] > 30 && p[0] < 33 && p[1] > 22 && p[1] < 31.5;
    if (inside(p, DESERT) && !nile && r() < 0.9) continue;
    const v = visible(p);
    if (!v) continue;
    n++;
    lights.push({
      x: v.x,
      y: v.y,
      r: round(1.6 + r() * 2.2 * v.facing),
      color: r() < 0.75 ? P.sun : P.paper,
      ring: false,
      big: false,
    });
  }
  return lights;
}

// Computed once: the shapes never change.
const LAND_PATHS = Object.values(LAND).map(pathOf);
const DESERT_PATH = pathOf(DESERT);
const ICE_CAP = pathOf([
  [-180, 72],
  [-90, 72],
  [0, 72],
  [90, 72],
  [180, 72],
  [180, 90],
  [-180, 90],
  [-180, 72],
]);
const GREENLAND = pathOf(LAND.greenland);
const CLOUD_PATHS = CLOUDS.map(([p, w, h, rot]) => pathOf(ellipseAround(p, w, h, rot)));
const LIGHTS = makeLights();

export function Earth() {
  const { cx, cy, R } = GLOBE;
  return (
    <g>
      <defs>
        <clipPath id="launch-earth-clip">
          <circle cx={cx} cy={cy} r={R} />
        </clipPath>
        <clipPath id="launch-earth-land">
          {LAND_PATHS.map((d, i) => (
            <path key={i} d={d} />
          ))}
        </clipPath>
        <radialGradient
          id="launch-earth-ocean"
          cx={cx}
          cy={cy - R}
          r={R * 1.2}
          gradientUnits="userSpaceOnUse"
        >
          <stop offset="0" stopColor="#3a8ee8" />
          <stop offset=".35" stopColor="#1f5fb8" />
          <stop offset=".75" stopColor="#173a7a" />
          <stop offset="1" stopColor="#0f2350" />
        </radialGradient>
        <radialGradient id="launch-earth-night" cx=".5" cy="0" r=".75">
          <stop offset=".25" stopColor={P.ink} stopOpacity={0} />
          <stop offset="1" stopColor={P.ink} stopOpacity={0.5} />
        </radialGradient>
      </defs>
      <circle
        cx={cx}
        cy={cy}
        r={R + 26}
        fill="none"
        stroke={P.teal}
        strokeOpacity={0.14}
        strokeWidth={48}
      />
      <circle
        cx={cx}
        cy={cy}
        r={R + 8}
        fill="none"
        stroke="#8fd3ff"
        strokeOpacity={0.22}
        strokeWidth={12}
      />
      <g clipPath="url(#launch-earth-clip)">
        <circle cx={cx} cy={cy} r={R} fill="url(#launch-earth-ocean)" />
        <path
          d={LAND_PATHS.join("")}
          fill="#4cbf7f"
          stroke="#2c8a57"
          strokeWidth={2}
          strokeLinejoin="round"
        />
        <g clipPath="url(#launch-earth-land)">
          <path d={DESERT_PATH} fill="#d9c27f" fillOpacity={0.6} />
        </g>
        <path d={ICE_CAP} fill="#eef6ff" fillOpacity={0.9} />
        <path d={GREENLAND} fill="#eef6ff" stroke="#b9d3ea" strokeWidth={2} />
        {CLOUD_PATHS.map((d, i) => (
          <path key={i} d={d} fill="#fff" fillOpacity={0.28} />
        ))}
        <circle cx={cx} cy={cy} r={R} fill="url(#launch-earth-night)" />
        {LIGHTS.map((l, i) => (
          <g key={i} data-light>
            <circle
              cx={l.x}
              cy={l.y}
              r={l.r * (l.big ? 3.4 : 2.6)}
              fill={l.color}
              fillOpacity={l.big ? 0.22 : 0.16}
            />
            <circle cx={l.x} cy={l.y} r={l.r} fill={l.color} />
            {l.ring && (
              <circle
                cx={l.x}
                cy={l.y}
                r={l.r * 6.5}
                fill="none"
                stroke={l.color}
                strokeOpacity={0.55}
                strokeWidth={2}
              />
            )}
          </g>
        ))}
      </g>
      <circle
        cx={cx}
        cy={cy}
        r={R}
        fill="none"
        stroke="#8fd3ff"
        strokeOpacity={0.7}
        strokeWidth={2.5}
      />
    </g>
  );
}
